      font-weight: 700;
      letter-spacing: 0.08em;
      text-transform: uppercase;
    }

    h1 {
      margin: 18px 0 14px;
      font-size: clamp(2.3rem, 5vw, 4rem);
      line-height: 1;
      letter-spacing: -0.04em;
